CREATE SCHEMA IF NOT EXISTS lms;
COMMENT ON SCHEMA lms IS 'Learning Management: Online courses (chapters, lessons, SCORM), enrolments and progress, cohorts with live classes and timetables, quizzes, assignments, programming exercises, learning programs, evaluations, certificates and badges. LMS participation is not school attendance and LMS grades are not official results.';

