    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_course PRIMARY KEY (id),
    CONSTRAINT ck_course_status CHECK (status IN ('in_progress', 'under_review', 'approved')),
    CONSTRAINT ck_course_card_gradient CHECK (card_gradient IN ('red', 'blue', 'green', 'amber', 'cyan', 'orange', 'pink', 'purple', 'teal', 'violet', 'yellow', 'gray')),
    CONSTRAINT ck_course_lifecycle_status CHECK (lifecycle_status IN ('draft', 'published', 'deactivated')),
    CONSTRAINT ck_course_delivery_modality CHECK (delivery_modality IN ('traditional', 'online', 'hybrid')),
