CREATE TABLE lms.cohort (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    institution_id uuid,
    title varchar(200) NOT NULL,
    description text,
    details text,
    category_id uuid,
    medium varchar(30) NOT NULL DEFAULT  'online',
    start_date date NOT NULL,
    end_date date NOT NULL,
    start_time time,
    end_time time,
    timezone varchar(64) NOT NULL,
    seat_count integer,
    is_published boolean NOT NULL DEFAULT false,
    allow_self_enrollment boolean NOT NULL DEFAULT false,
    allow_future_access boolean NOT NULL DEFAULT true,
    is_paid boolean NOT NULL DEFAULT false,
    price numeric(14,2),
    currency_id uuid,
    price_usd numeric(14,2),
    show_live_class boolean NOT NULL DEFAULT false,
    evaluation_enabled boolean NOT NULL DEFAULT false,
    evaluation_end_date date,
    certification_enabled boolean NOT NULL DEFAULT false,
    conferencing_provider varchar(30),
    conferencing_account_id uuid,
    timetable_template_id uuid,
    confirmation_template_id uuid,
    meta_image_file_id uuid,
    intro_video_file_id uuid,
    custom_component text,
    custom_script text,
    publish_notification_sent boolean NOT NULL DEFAULT false,
    code varchar(50),
    academic_term_id uuid,
    program_id uuid,
    external_ref varchar(100),
    lifecycle_status varchar(30) NOT NULL DEFAULT  'draft',
    staff_access_from timestamptz,
    staff_access_until timestamptz,
    student_access_from timestamptz,
    student_access_until timestamptz,
    has_schedule boolean NOT NULL DEFAULT false,
    staff_can_edit_schedule boolean NOT NULL DEFAULT false,
    grade_display varchar(30) NOT NULL DEFAULT  'points',
    grading_scheme_id uuid,
    enrollment_opens_at timestamptz,
    enrollment_closes_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    class_subject_id uuid,
    batch_id uuid,
    academic_year_id uuid,
    CONSTRAINT pk_cohort PRIMARY KEY (id),
    CONSTRAINT ck_cohort_medium CHECK (medium IN ('online', 'offline')),
    CONSTRAINT ck_cohort_conferencing_provider CHECK (conferencing_provider IN ('zoom', 'google_meet')),
    CONSTRAINT ck_cohort_lifecycle_status CHECK (lifecycle_status IN ('draft', 'active', 'suspended', 'completed', 'archived')),
    CONSTRAINT ck_cohort_grade_display CHECK (grade_display IN ('points', 'percentage')),
    CONSTRAINT ck_cohort_1 CHECK (end_date >= start_date),
    CONSTRAINT uq_cohort_id_tenant UNIQUE (id, tenant_id)
);
