CREATE TABLE lms.settings (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    livecode_url varchar(500),
    default_currency_id uuid,
    apply_gst boolean NOT NULL DEFAULT false,
    show_usd_equivalent boolean NOT NULL DEFAULT false,
    apply_rounding boolean NOT NULL DEFAULT false,
    payment_gateway varchar(60),
    identify_user_category boolean NOT NULL DEFAULT false,
    persona_captured boolean NOT NULL DEFAULT false,
    lms_is_default_home boolean NOT NULL DEFAULT false,
    send_calendar_invite_for_evaluations boolean NOT NULL DEFAULT false,
    allow_guest_access boolean NOT NULL DEFAULT true,
    disable_signup boolean NOT NULL DEFAULT true,
    disable_pwa boolean NOT NULL DEFAULT false,
    allow_job_posting boolean NOT NULL DEFAULT true,
    certified_members_page boolean NOT NULL DEFAULT false,
    prevent_skipping_videos boolean NOT NULL DEFAULT false,
    lesson_dwell_seconds integer NOT NULL DEFAULT 30,
    enforce_video_completion boolean NOT NULL DEFAULT true,
    enforce_quiz_completion boolean NOT NULL DEFAULT true,
    enforce_quiz_passing boolean NOT NULL DEFAULT true,
    enforce_open_ended_quiz_passing boolean NOT NULL DEFAULT true,
    enforce_assignment_completion boolean NOT NULL DEFAULT true,
    enforce_assignment_passing boolean NOT NULL DEFAULT false,
    enforce_exercise_completion boolean NOT NULL DEFAULT false,
    enforce_exercise_passing boolean NOT NULL DEFAULT false,
    show_courses boolean NOT NULL DEFAULT true,
    show_students boolean NOT NULL DEFAULT true,
    show_assessments boolean NOT NULL DEFAULT true,
    show_live_class boolean NOT NULL DEFAULT true,
    show_discussions boolean NOT NULL DEFAULT true,
    show_emails boolean NOT NULL DEFAULT true,
    show_dashboard boolean NOT NULL DEFAULT true,
    show_day_view boolean NOT NULL DEFAULT false,
    text_direction varchar(30) NOT NULL DEFAULT  'auto',
    notify_published_courses varchar(30),
    notify_published_cohorts varchar(30),
    send_payment_reminders_cohort boolean NOT NULL DEFAULT false,
    send_payment_reminders_course boolean NOT NULL DEFAULT false,
    mentor_request_template_id uuid,
    mentor_status_template_id uuid,
    cohort_confirmation_template_id uuid,
    certificate_template_id uuid,
    payment_reminder_template_id uuid,
    custom_signup_content text,
    meta_description text,
    meta_keywords text,
    meta_image_file_id uuid,
    contact_us_email varchar(320),
    contact_us_url varchar(500),
    unsplash_access_key_enc text,
    demo_data_present boolean NOT NULL DEFAULT false,
