    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_settings PRIMARY KEY (id),
    CONSTRAINT ck_settings_text_direction CHECK (text_direction IN ('auto', 'ltr', 'rtl')),
    CONSTRAINT ck_settings_notify_published_courses CHECK (notify_published_courses IN ('email', 'in_app')),
    CONSTRAINT ck_settings_notify_published_cohorts CHECK (notify_published_cohorts IN ('email', 'in_app')),
