CREATE TABLE lms.content_item (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    chapter_id uuid,
    course_id uuid,
    cohort_id uuid,
    item_kind varchar(30) NOT NULL,
    lesson_id uuid,
    file_id uuid,
    assignment_id uuid,
    quiz_id uuid,
    discussion_prompt_id uuid,
    participation_activity_id uuid,
    web_resource_id uuid,
    ebook_id uuid,
    external_tool_resource_id uuid,
    live_class_id uuid,
    link_url varchar(1000),
    title varchar(255),
    sort_order integer NOT NULL DEFAULT 0,
    is_active boolean NOT NULL DEFAULT true,
    is_always_visible boolean NOT NULL DEFAULT true,
    visible_from timestamptz,
    visible_until timestamptz,
    visible_until_cohort_end boolean NOT NULL DEFAULT false,
    attempt_from timestamptz,
    due_at timestamptz,
    attempt_until_cohort_end boolean NOT NULL DEFAULT false,
    visible_start_day integer,
    visible_start_time time,
    visible_end_day integer,
    visible_end_time time,
    attempt_start_day integer,
    attempt_start_time time,
    attempt_end_day integer,
    attempt_end_time time,
    late_submission_allowed boolean NOT NULL DEFAULT false,
    late_submission_days integer,
    is_graded boolean NOT NULL DEFAULT false,
    points numeric(8,2),
    weight_percent numeric(5,2),
    grading_category_id uuid,
    rubric_id uuid,
    plagiarism_check_required boolean NOT NULL DEFAULT false,
    show_in_calendar boolean NOT NULL DEFAULT true,
    allow_delete boolean NOT NULL DEFAULT true,
    allow_edit_details boolean NOT NULL DEFAULT true,
    allow_edit_dates boolean NOT NULL DEFAULT true,
    allow_edit_grading boolean NOT NULL DEFAULT true,
    copied_from_id uuid,
    is_original boolean NOT NULL DEFAULT true,
    view_count bigint NOT NULL DEFAULT 0,
    like_count bigint NOT NULL DEFAULT 0,
    rating_total numeric(12,2) NOT NULL DEFAULT 0,
    rating_count integer NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    exercise_id uuid,
    CONSTRAINT pk_content_item PRIMARY KEY (id),
    CONSTRAINT ck_content_item_item_kind CHECK (item_kind IN ('lesson', 'file', 'assignment', 'quiz', 'discussion', 'participation', 'web_resource', 'ebook', 'external_tool', 'live_class', 'link', 'exercise')),
    CONSTRAINT ck_content_item_1 CHECK (num_nonnulls(lesson_id, file_id, assignment_id, quiz_id, discussion_prompt_id, participation_activity_id, web_resource_id, ebook_id, external_tool_resource_id, live_class_id, link_url, exercise_id) = 1),
    CONSTRAINT ck_content_item_2 CHECK ((item_kind = 'lesson') = (lesson_id IS NOT NULL) AND (item_kind = 'file') = (file_id IS NOT NULL) AND (item_kind = 'assignment') = (assignment_id IS NOT NULL) AND (item_kind = 'quiz') = (quiz_id IS NOT NULL) AND (item_kind = 'discussion') = (discussion_prompt_id IS NOT NULL) AND (item_kind = 'participation') = (participation_activity_id IS NOT NULL) AND (item_kind = 'web_resource') = (web_resource_id IS NOT NULL) AND (item_kind = 'ebook') = (ebook_id IS NOT NULL) AND (item_kind = 'external_tool') = (external_tool_resource_id IS NOT NULL) AND (item_kind = 'live_class') = (live_class_id IS NOT NULL) AND (item_kind = 'link') = (link_url IS NOT NULL) AND (item_kind = 'exercise') = (exercise_id IS NOT NULL)),
    CONSTRAINT ck_content_item_placement CHECK ((chapter_id IS NOT NULL AND course_id IS NOT NULL) OR cohort_id IS NOT NULL),
    CONSTRAINT uq_content_item_id_tenant UNIQUE (id, tenant_id)
);
COMMENT ON TABLE lms.content_item IS 'Item placed in a chapter (folder) of a course template or of a cohort: lesson, file, assignment, quiz, discussion, participation activity, web resource, e-book, external tool, live class or link — with visibility, attempt window and grading settings.';
COMMENT ON COLUMN lms.content_item.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN lms.content_item.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
