-- === P0-07: files/import-export/access-log tables moved from platform (they are LMS features) ===

CREATE TABLE lms.import_export_job (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    institution_id uuid,
    direction varchar(30) NOT NULL,
    package_format varchar(30) NOT NULL,
    scope varchar(30) NOT NULL,
    course_id uuid,
    cohort_id uuid,
    target_chapter_id uuid,
    add_to_repository boolean NOT NULL DEFAULT false,
    package_file_id uuid,
    requested_by uuid NOT NULL,
    requested_on date NOT NULL,
    started_on date,
    status varchar(30) NOT NULL DEFAULT  'pending',
    unarchive_status varchar(30),
    error_log text,
    cohort_code varchar(50),
    cohort_start_date date,
    course_code varchar(50),
    course_version varchar(20),
    course_title varchar(200),
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_import_export_job PRIMARY KEY (id),
    CONSTRAINT ck_import_export_job_direction CHECK (direction IN ('import', 'export')),
    CONSTRAINT ck_import_export_job_package_format CHECK (package_format IN ('native', 'common_cartridge', 'cohort_archive')),
    CONSTRAINT ck_import_export_job_scope CHECK (scope IN ('course', 'cohort')),
    CONSTRAINT ck_import_export_job_status CHECK (status IN ('pending', 'in_progress', 'complete', 'error', 'cancelled')),
    CONSTRAINT ck_import_export_job_unarchive_status CHECK (unarchive_status IN ('pending', 'in_progress', 'complete', 'error')),
    CONSTRAINT ck_import_export_job_1 CHECK (NOT (course_id IS NOT NULL AND cohort_id IS NOT NULL))
);
COMMENT ON TABLE lms.import_export_job IS 'Background import or export of a course or cohort package (native or IMS Common Cartridge).';
COMMENT ON COLUMN lms.import_export_job.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN lms.import_export_job.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN lms.import_export_job.institution_id IS 'Institution the job runs for.';
COMMENT ON COLUMN lms.import_export_job.direction IS 'Import or export.';
COMMENT ON COLUMN lms.import_export_job.package_format IS 'Package format.';
COMMENT ON COLUMN lms.import_export_job.scope IS 'Whether a course template or a cohort (class) is transferred.';
COMMENT ON COLUMN lms.import_export_job.course_id IS 'Course imported into / exported from.';
COMMENT ON COLUMN lms.import_export_job.cohort_id IS 'Cohort imported into / exported from.';
COMMENT ON COLUMN lms.import_export_job.target_chapter_id IS 'Chapter (folder) the imported content is placed in.';
COMMENT ON COLUMN lms.import_export_job.add_to_repository IS 'Also add imported items to the shared content repository.';
COMMENT ON COLUMN lms.import_export_job.package_file_id IS 'Package file (uploaded for import, produced by export).';
COMMENT ON COLUMN lms.import_export_job.requested_by IS 'User who requested the job.';
COMMENT ON COLUMN lms.import_export_job.requested_on IS 'Request date.';
COMMENT ON COLUMN lms.import_export_job.started_on IS 'Date the worker started the job.';
COMMENT ON COLUMN lms.import_export_job.status IS 'Job state.';
COMMENT ON COLUMN lms.import_export_job.unarchive_status IS 'Restore state of an exported cohort archive.';
COMMENT ON COLUMN lms.import_export_job.error_log IS 'Error details.';
COMMENT ON COLUMN lms.import_export_job.cohort_code IS 'Cohort code recorded in the package.';
COMMENT ON COLUMN lms.import_export_job.cohort_start_date IS 'Cohort start date recorded in the package.';
COMMENT ON COLUMN lms.import_export_job.course_code IS 'Course code recorded in the package.';
COMMENT ON COLUMN lms.import_export_job.course_version IS 'Course version recorded in the package.';
COMMENT ON COLUMN lms.import_export_job.course_title IS 'Course title recorded in the package.';
COMMENT ON COLUMN lms.import_export_job.created_at IS 'Row creation time.';
COMMENT ON COLUMN lms.import_export_job.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN lms.import_export_job.updated_at IS 'Last update time.';
COMMENT ON COLUMN lms.import_export_job.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN lms.import_export_job.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN lms.import_export_job.row_version IS 'Optimistic-locking version.';

CREATE TABLE lms.access_log (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    user_id uuid,
    accessed_at timestamptz NOT NULL,
    operation varchar(120),
    url varchar(1000),
    params text,
    is_async boolean NOT NULL DEFAULT false,
    session_ref varchar(128),
    cohort_id uuid,
    role_name varchar(100),
    course_week varchar(20),
    analytics_link_ref varchar(100),
    user_agent varchar(500),
    referer varchar(1000),
    ip_address inet,
    CONSTRAINT pk_access_log PRIMARY KEY (id, accessed_at)
) PARTITION BY RANGE (accessed_at);
CREATE TABLE lms.access_log_default PARTITION OF lms.access_log DEFAULT;
COMMENT ON TABLE lms.access_log IS 'Page / API access record for learning analytics and security review (high volume; partition by month).';
COMMENT ON COLUMN lms.access_log.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN lms.access_log.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN lms.access_log.user_id IS 'User.';
COMMENT ON COLUMN lms.access_log.accessed_at IS 'Access time.';
COMMENT ON COLUMN lms.access_log.operation IS 'Operation performed.';
COMMENT ON COLUMN lms.access_log.url IS 'Requested URL.';
COMMENT ON COLUMN lms.access_log.params IS 'Request parameters (sensitive values removed).';
COMMENT ON COLUMN lms.access_log.is_async IS 'Background (XHR / API) request rather than a page view.';
COMMENT ON COLUMN lms.access_log.session_ref IS 'External session identifier (hashed web/mobile session).';
COMMENT ON COLUMN lms.access_log.cohort_id IS 'Cohort context.';
COMMENT ON COLUMN lms.access_log.role_name IS 'Role the user acted in.';
COMMENT ON COLUMN lms.access_log.course_week IS 'Course week of the cohort at the time.';
COMMENT ON COLUMN lms.access_log.analytics_link_ref IS 'External analytics link identifier.';
COMMENT ON COLUMN lms.access_log.user_agent IS 'Browser / app user agent.';
COMMENT ON COLUMN lms.access_log.referer IS 'HTTP referer.';
COMMENT ON COLUMN lms.access_log.ip_address IS 'Client IP address.';

CREATE TABLE lms.drive_item (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    owner_user_id uuid NOT NULL,
    file_id uuid,
    item_type varchar(40),
    icon varchar(100),
    title varchar(255) NOT NULL,
    description text,
    keywords varchar(500),
    size_bytes bigint,
    link_url varchar(1000),
    uploaded_at timestamptz NOT NULL DEFAULT now(),
    course_id uuid,
    is_shared boolean NOT NULL DEFAULT false,
    like_count integer NOT NULL DEFAULT 0,
    dislike_count integer NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_drive_item PRIMARY KEY (id),
    CONSTRAINT ck_drive_item_1 CHECK (file_id IS NOT NULL OR link_url IS NOT NULL),
    CONSTRAINT uq_drive_item_id_tenant UNIQUE (id, tenant_id)
);
COMMENT ON TABLE lms.drive_item IS 'File or link in a user''s personal file cabinet (drive).';
COMMENT ON COLUMN lms.drive_item.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN lms.drive_item.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN lms.drive_item.owner_user_id IS 'Owner.';
COMMENT ON COLUMN lms.drive_item.file_id IS 'Stored file (NULL for a link).';
COMMENT ON COLUMN lms.drive_item.item_type IS 'File type label (document, presentation, video, link...).';
COMMENT ON COLUMN lms.drive_item.icon IS 'Icon key shown in the drive.';
COMMENT ON COLUMN lms.drive_item.title IS 'Title.';
COMMENT ON COLUMN lms.drive_item.description IS 'Description.';
COMMENT ON COLUMN lms.drive_item.keywords IS 'Search keywords.';
COMMENT ON COLUMN lms.drive_item.size_bytes IS 'Size in bytes.';
COMMENT ON COLUMN lms.drive_item.link_url IS 'URL when the item is a link.';
COMMENT ON COLUMN lms.drive_item.uploaded_at IS 'Upload time.';
COMMENT ON COLUMN lms.drive_item.course_id IS 'Course the item relates to.';
COMMENT ON COLUMN lms.drive_item.is_shared IS 'Shared with at least one user (see lms.drive_item_share).';
COMMENT ON COLUMN lms.drive_item.like_count IS 'Cached likes.';
COMMENT ON COLUMN lms.drive_item.dislike_count IS 'Cached dislikes.';
COMMENT ON COLUMN lms.drive_item.created_at IS 'Row creation time.';
COMMENT ON COLUMN lms.drive_item.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN lms.drive_item.updated_at IS 'Last update time.';
COMMENT ON COLUMN lms.drive_item.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN lms.drive_item.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN lms.drive_item.row_version IS 'Optimistic-locking version.';

CREATE TABLE lms.drive_item_share (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    drive_item_id uuid NOT NULL,
    user_id uuid NOT NULL,
    reaction varchar(30),
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_drive_item_share PRIMARY KEY (id),
    CONSTRAINT ck_drive_item_share_reaction CHECK (reaction IN ('like', 'dislike'))
);
COMMENT ON TABLE lms.drive_item_share IS 'User a drive item is shared with, and that user''s like / dislike of it.';
COMMENT ON COLUMN lms.drive_item_share.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN lms.drive_item_share.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN lms.drive_item_share.drive_item_id IS 'Drive item.';
COMMENT ON COLUMN lms.drive_item_share.user_id IS 'User the item is shared with.';
COMMENT ON COLUMN lms.drive_item_share.reaction IS 'The user''s reaction (NULL = none).';
COMMENT ON COLUMN lms.drive_item_share.created_at IS 'Row creation time.';
COMMENT ON COLUMN lms.drive_item_share.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN lms.drive_item_share.updated_at IS 'Last update time.';
COMMENT ON COLUMN lms.drive_item_share.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN lms.drive_item_share.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN lms.drive_item_share.row_version IS 'Optimistic-locking version.';

