ALTER TABLE lms.access_log FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON lms.access_log USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
ALTER TABLE lms.annotation ENABLE ROW LEVEL SECURITY;
ALTER TABLE lms.annotation FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON lms.annotation USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
