CREATE POLICY tenant_isolation ON lms.annotation_share USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
ALTER TABLE lms.assignment ENABLE ROW LEVEL SECURITY;
ALTER TABLE lms.assignment FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON lms.assignment USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
ALTER TABLE lms.assignment_group ENABLE ROW LEVEL SECURITY;
ALTER TABLE lms.assignment_group FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON lms.assignment_group USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
